export function parseStage2Reply(text: string): Stage2Parsed | null {
  const match = text.match(STAGE2_PATTERN)
  if (!match) return null
  const [, numberText, reflection, question] = match
  const questionNumber = Number(numberText)
  if (!Number.isFinite(questionNumber) || questionNumber < 1 || questionNumber > 10) return null
  const trimmedReflection = reflection.trim()
  const trimmedQuestion = question.trim()
  if (!trimmedQuestion) return null
  return { questionNumber, reflection: trimmedReflection, question: trimmedQuestion }
}
