export function parseStage3Report(text: string): Stage3Parsed | null {
  if (!isFinalReport(text)) return null

  const summary: SummarySection[] = []
  // 行 113-119：依序切出五個報告段落（issue/status/strengths/directions）
  for (const key of ['issue', 'status', 'strengths', 'directions'] as const) {
    const marker = SECTION_MARKERS[key]
    const body = extractBetween(text, marker, nextMarkersAfter(marker))
    if (!body) continue
    const items = toItems(body)  // 若為列表項則拆分
    summary.push({ key, title: SECTION_TITLES[key], body, ...(items ? { items } : {}) })
  }

  // 行 121-130：切出推薦資源段落，用正規表達式逐項解析
  const resourceBody = extractBetween(text, SECTION_MARKERS.resources, [])
  if (resourceBody) {
    const resources = parseResources(resourceBody)
    summary.push({
      key: 'resources',
      title: SECTION_TITLES.resources,
      body: resourceBody,
      ...(resources.length ? { resources } : {})
    })
  }

  if (summary.length === 0) {
    // 一個段落都切不出來，回傳原始全文當單一段落
    return { summary: [{ key: 'raw', title: '總結報告', body: text }] }
  }

  // 行 138-151：解析 FAST 象限資訊
  let fast: Stage3Parsed['fast']
  const fastBody = extractBetween(text, SECTION_MARKERS.fastBlock, nextMarkersAfter(SECTION_MARKERS.fastBlock))
  const adviceBody = extractBetween(text, SECTION_MARKERS.advice, nextMarkersAfter(SECTION_MARKERS.advice))
  if (fastBody) {
    const directionMatch = fastBody.match(/學習方向明確度[：:]\s*([\d.]+)/)
    const resourceMatch = fastBody.match(/學習資源掌握度[：:]\s*([\d.]+)/)
