export function buildSelfAwarenessCard(
  topicLabel: string,
  summary: SummarySection[]
): { coreInsight: string; nextExplorationDirection: string; resources: RecommendedResource[] } {
  const issue = summary.find(s => s.key === 'issue')
  const directions = summary.find(s => s.key === 'directions')
  const resourcesSection = summary.find(s => s.key === 'resources')

  const firstSentence = (text: string | undefined): string => {
    if (!text) return topicLabel
    // 按「。！？」分割，取第一句
    const first = text.split(/(?<=[。！？])/).find(Boolean)
    return (first ?? text).trim()
  }

  return {
    // 行 177：從 issue 段落取第一句作為核心洞察
    coreInsight: firstSentence(issue?.body),
    // 行 178：從 directions 取第一個條列項，或若無項則取第一句
    nextExplorationDirection: directions?.items?.[0] ?? firstSentence(directions?.body),
    // 行 179：從 resources 段落的已解析資源清單
    resources: resourcesSection?.resources ?? []
  }
}
