### 6. SSE 串流解析

**檔案**: `d:\_ntu台大\aiProject\_dev\_frontend/chatai/apps/explore/src/services/advisingApi.ts` (行 74-126)

```typescript
export async function sendAdvisingMessage(
  explorationId: string,
  content: string,
  onDelta?: (delta: string, accumulated: string) => void
): Promise<string> {
  // ... 簽名與認證 ...

  const res = await fetch(getApiUrl('/api/run?stream=true'), {
    method: 'POST',
    headers: { /* ... */ },
    body: JSON.stringify({ input_value: content, exploration_id: explorationId, model: readModelPreference() })
  })

  const reader = res.body.getReader()
  const decoder = new TextDecoder('utf-8')
  let buffer = ''
  let accumulated = ''

  while (true) {
    const { done, value } = await reader.read()
    if (done) break
    buffer += decoder.decode(value, { stream: true })
    const events = buffer.split('\n\n')  // SSE 事件以 \n\n 分隔
    buffer = events.pop() ?? ''
    for (const raw of events) {
      const payload = parseSseLine(raw)  // 解析 "data: {...}" 行
      if (!payload) continue
      if (payload.error) throw new AdvisingApiError(payload.error)
      if (payload.delta) {
        accumulated += payload.delta
        onDelta?.(payload.delta, accumulated)
      }
    }
  }

  return accumulated
}

// 行 44-49：SSE 行解析
function parseSseLine(rawLine: string): SseStreamPayload | null {
  const line = rawLine.trim()
  if (!line.startsWith('data: ')) return null
  return JSON.parse(line.slice('data: '.length))
}
```

